// ===========================================
// SMART ALERT SYSTEM - MAIN APP COMPONENT
// ===========================================
// This is the root component of the React application
// It handles routing between different pages of the system

import React from "react";                    // React library for building user interfaces
import { Routes, Route, Navigate } from "react-router-dom";  // React Router for navigation
import Students from "./pages/Students";      // Student management page
import Attendance from "./pages/Attendance";  // Mark attendance page
import AttendanceRecords from "./pages/AttendanceRecords";  // View attendance records page
import ParentView from "./pages/ParentView";  // Parent view page
import './index.css';                        // Global CSS styles

// ===========================================
// MAIN APP COMPONENT
// ===========================================
const App = () => {
  return (
    <div className="fade-in">
      {/* Define all application routes */}
      <Routes>
        {/* Default route - Student management page */}
        <Route path="/" element={<Students />} />

        {/* Attendance marking page */}
        <Route path="/attendance" element={<Attendance />} />

        {/* Attendance records viewing page */}
        <Route path="/records" element={<AttendanceRecords />} />

        {/* Parent view page for checking student attendance */}
        <Route path="/parent" element={<ParentView />} />

        {/* Catch-all route - redirect unknown paths to home */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </div>
  );
};

// Export the App component as the default export
export default App;
